/* SAA Series D & E — brand date-tile fonts (Fontspring-licensed), base64-embedded
   so they resolve inside the bulletin preview iframe (srcdoc has no base URL) and
   embed into the exported PDF. Source .otf files live in assets/fonts/. */
window.BULLETIN_FONTS_CSS = "@font-face{font-family:'SAA D';src:url(data:font/otf;base64,) format('opentype');font-display:swap}@font-face{font-family:'SAA E';src:url(data:font/otf;base64,) format('opentype');font-display:swap}";
